const label = ({ dataset: { choices, labels } }, value) =>
  choices ? labels.split('|')[choices.split(',').indexOf(value)] : Number(value).toLocaleString('en');
levers.forEach((lever) => (lever.textContent = label(lever, lever.dataset.value)));
